            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, gangs):
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if gangs[i] != gangs[j]:
                edges.append((abs(gangs[i] - gangs[j]), i, j))

    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    mst_edges = []
    for weight, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u + 1, v + 1))
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) == n - 1:
        return "YES\n" + "\n".join(map(str, mst_edges))
    else:
        return "NO"

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        gangs = list(map(int, data[index:index + n]))
        index += n

        result = kruskal(n, gangs)
        results.append(result)

    for result in results:
        print(result)

